		const bal = Number(prof?.wallet_balance ?? 0);
		if (bal < finalFare) throw new Error(`Saldo insuficiente (${bal.toFixed(2)}). Deposite via Pix ou escolha Pix/Dinheiro.`);
		const nextBal = Number((bal - finalFare).toFixed(2));
